int findTargetSumWays(int*a,int n,int target){
    int dp[W]={0},nd[W]={0};dp[O]=1;
    for(int i=0;i<n;i++){memset(nd,0,sizeof(nd));for(int s=-1000;s<=1000;s++){int c=dp[s+O];if(!c)continue;if(s+a[i]<=1000)nd[s+a[i]+O]+=c;if(s-a[i]>=-1000)nd[s-a[i]+O]+=c;}memcpy(dp,nd,sizeof(dp));}
    if(target<-1000||target>1000)return 0;return dp[target+O];
}

