class Solution{
public:int findTargetSumWays(vector<int>& nums,int target){
    unordered_map<int,int> dp,nd;dp[0]=1;
    for(int x:nums){nd.clear();for(auto&p:dp){nd[p.first+x]+=p.second;nd[p.first-x]+=p.second;}dp.swap(nd);}
    return dp.count(target)?dp[target]:0;
}};

