class Solution{
    public int findTargetSumWays(int[] nums,int target){
        Map<Integer,Integer> dp=new HashMap<>();dp.put(0,1);
        for(int x:nums){
            Map<Integer,Integer> nd=new HashMap<>();
            for(Map.Entry<Integer,Integer> e:dp.entrySet()){
                int s=e.getKey(),c=e.getValue();
                nd.put(s+x,nd.getOrDefault(s+x,0)+c);
                nd.put(s-x,nd.getOrDefault(s-x,0)+c);
            }dp=nd;
        }return dp.getOrDefault(target,0);
    }
}

